<div class="mb-4"><h1 class="h3"><?= $person ? 'Edit user' : 'Create user' ?></h1></div><div class="card"><div class="card-body"><form method="post" action="<?= $person ? site_url('admin/users/' . $person['id'] . '/edit') : site_url('admin/users') ?>"><?= csrf_field() ?><div class="mb-3"><label class="form-label" for="name">Full name</label><input class="form-control" id="name" name="name" maxlength="120" required value="<?= esc(old('name', $person['name'] ?? '')) ?>"></div><div class="mb-3"><label class="form-label" for="email">Email</label><input class="form-control" type="email" id="email" name="email" maxlength="190" required value="<?= esc(old('email', $person['email'] ?? '')) ?>"></div><div class="mb-3"><label class="form-label" for="department">Department</label><input class="form-control" id="department" name="department" maxlength="120" value="<?= esc(old('department', $person['department'] ?? '')) ?>"></div><div class="mb-3"><label class="form-label" for="role">Role</label><select class="form-select" id="role" name="role" required><?php foreach (['Employee','IT Support','IT Manager','Administrator'] as $role): ?><option <?= old('role', $person['role'] ?? 'Employee') === $role ? 'selected' : '' ?>><?= esc($role) ?></option><?php endforeach ?></select></div><?php if (! $person): ?><div class="mb-3"><label class="form-label" for="password">Initial password</label><input class="form-control" type="password" id="password" name="password" minlength="12" autocomplete="new-password" required><div class="form-text">At least 12 characters. Share it securely with the user.</div></div><?php endif ?><button class="btn btn-primary">Save user</button> <a class="btn btn-outline-secondary" href="<?= site_url('admin/users') ?>">Cancel</a></form></div></div>
